update public.mcq_questions set prompt = 'Which command prints the version of Python installed on your computer?', options = '[{"id": "a", "text": "python -v"}, {"id": "b", "text": "python --version"}, {"id": "c", "text": "python --check"}]'::jsonb, correct_option_id = 'b', explanation_correct = '`python --version` prints the installed version. On macOS and Linux you may need `python3 --version`.', explanation_incorrect = 'Not quite. `python -v` turns on verbose mode, which traces every import. The command that prints the version is `python --version`.', shuffle_options = false where id = '00000000-0000-4000-8000-0000000000a1';
update public.mcq_questions set prompt = 'Which statement about notebook cells is true?', options = '[{"id": "a", "text": "Each cell can be run on its own, and all cells share the same variables while the kernel is running"}, {"id": "b", "text": "Every cell has its own separate set of variables"}, {"id": "c", "text": "Cells run automatically from top to bottom whenever you open the notebook"}]'::jsonb, correct_option_id = 'a', explanation_correct = 'Cells share one kernel, so a variable created in one cell can be used by any cell you run afterwards.', explanation_incorrect = 'Not quite. Cells are separate to run but share the same kernel, so variables carry over. You choose when each cell runs.', shuffle_options = true where id = '00000000-0000-4000-8000-0000000000a2';
update public.mcq_questions set prompt = 'After running `price = 20` and then `price = price + 5`, what does `print(price)` show?', options = '[{"id": "a", "text": "25"}, {"id": "b", "text": "20"}, {"id": "c", "text": "price + 5"}]'::jsonb, correct_option_id = 'a', explanation_correct = 'Python works out the right side first using the old value (20 + 5), then stores 25 back under `price`.', explanation_incorrect = 'Not quite. The second line reads the old value of `price`, adds 5, and stores the answer back, so `price` is now 25.', shuffle_options = false where id = '00000000-0000-4000-8000-0000000000a3';
